from pathlib import Path
from PIL import Image
import json,hashlib,sys
r=Path('outputs/case2_video2code_v1_native/runs')/sys.argv[1]/'evaluation'
manifest=json.loads((r/'manifest.json').read_text(encoding='utf8'))
patterns=['S00-reload-after','S01-reset-confirm-after','S01-hover-a-after','S01-hover-neighbor-after','S01-hover-away-after','S01-independent-1-placed-after','S01-independent-2-placed-after','S01-independent-3-placed-after','S01-new-settings-after','S02-primary-base-preview-after','S02-primary-base-placed-after','S02-primary-top-preview-after','S02-primary-top-placed-after','S02-floor-placed-after','S02-secondary-base-placed-after','S02-secondary-top-preview-after','S02-secondary-top-placed-after','S02-side-angle-after','S03-red22-placed-after','S03-green22-placed-after','S03-width3-after','S03-purple32-preview-after','S03-purple32-placed-after','S03-swap-after','S03-purple23-preview-after','S03-purple23-placed-after','S04-play-after','S04-rotate-1-after','S04-rotate-2-after','S04-rotate-3-after','S04-pause-after','S04-postplay-placed-after','S05-drag-after','S05-after-camera-placed-after','S06-setup-base-placed-after','S06-setup-top-placed-after','S06-purple-placed-after','S06-erase-mode-after','S06-green-hover-after','S06-green-delete-after','S06-camera-turn-after','S06-purple-hover-after','S06-purple-delete-after','S08-rebuild-on-red-preview-after','S08-rebuild-on-red-placed-after','S07-third-placed-after','S07-open-cancel-after','S07-modal-no-clickthrough-after','S07-cancel-after','S07-open-close-after','S07-close-after','S07-open-confirm-after','S07-confirm-after','S08-clear-rebuild-base-placed-after','S08-clear-rebuild-top-preview-after','S08-clear-rebuild-top-placed-after','S02-retarget-visible-seed-before-after','S02-retarget-visible-seed-result-after','S05-independent-reload-camera-after','S06-independent-camera-erase-hover-after','S06-independent-camera-erase-delete-after']
ids=[]
for pat in patterns:
    found=sorted(r.glob('*-'+pat+'.png'))
    if not found:continue
    src=found[-1];dst=src.with_suffix('.jpg');Image.open(src).convert('RGB').save(dst,quality=92,subsampling=0)
    id='J-'+src.stem;manifest['artifacts'][id]={'path':dst.name,'sha256':hashlib.sha256(dst.read_bytes()).hexdigest(),'kind':'candidate_screenshot','derived_from':src.name,'original_sha256':hashlib.sha256(src.read_bytes()).hexdigest(),'encoding':'full resolution JPEG quality 92; raw PNG retained'};ids.append(id)
notes=[{'scenario':'general','description':'All images are actual screenshots, with original PNG retained. Labels describe intended actions, not assumed successes. Judge from actual visible results plus logged coordinates. A scenario label saying top-placed does not assert that stacking succeeded.'},{'scenario':'S00','description':'Clean offline browser context; no candidate JS evaluated by Node. Trusted immutable npm server is the same supplied to all candidates. Evaluation uses 3002 to avoid interfering with generation; generation self-check used 3000. Original generation browser-log is also retained. Warnings alone do not fail E03.'},{'scenario':'S01','description':'Clear first. Move without clicking, then click three distinct scene points and change color/size. Compare position/independence and whether original entities change.'},{'scenario':'S02','description':'Red bottom requested at an interior grid point, green requested on its visible top; repeat purple/green at a different point and inspect side angle. If model placement is displaced, judge that actual failure rather than assuming successful setup.'},{'scenario':'S03-S05','description':'Create red/green 2x2 and purple 3x2; swap and place 2x3. Play, observe multiple timed frames over 5 seconds, attempt to pause using visible pause/play entry, then attempt editing and manual orbit. If Play cannot exit, subsequent programmatic size selection does not establish successful pause; use independent camera replay if supplied.'},{'scenario':'S06-S08','description':'Use visible colored targets to hover/delete, change camera, delete current target, rebuild on remaining red. Some setup states may be unreachable because of candidate placement defects. Additional independent camera/erase or seed-top retarget evidence is supplied when needed; no candidate source state is used to prove behavior.'},{'scenario':'S07','description':'Open clear modal, click an exterior board point to check no clickthrough (dismissal is acceptable), then cancel; reopen and close via x; reopen and confirm; rebuild afterwards.'}]
if sys.argv[1].startswith('gpt-6-luna'):
    notes.append({'scenario':'operator corrections','description':'Early audit stopped at Python child-process permission; rerun intact from reload with original files retained. A screenshot pixel locator initially targeted a ghost because the requested red placement had moved to the bottom edge behind the toolbar; do not treat that mistaken top attempt alone as valid stacking evidence. The controlled S02-retarget-visible-seed sequence directly targets the actual red seed at (639,435) after reload and is the conclusive correction. Independent camera/erase checks restart after failed Play/pause to isolate those functions. Judge the screenshots independently.'})
(r/'judge-selection.json').write_text(json.dumps({'images':ids,'notes':notes},ensure_ascii=False,indent=2),encoding='utf8')
for f in ['judge-selection.json']:
    manifest['artifacts'][Path(f).stem]={'path':f,'sha256':hashlib.sha256((r/f).read_bytes()).hexdigest(),'kind':'browser_log'}
(r/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf8');print(json.dumps({'images':len(ids),'run':sys.argv[1]}))
